const EXPECTED_TOKEN = 'REPLACE_WITH_ADVANCE_INTERNAL_TOKEN';
const item = $input.first();
const headers = item.json.headers || {};
if (headers['x-advance-token'] !== EXPECTED_TOKEN) {
  return [];
}
return [{ json: item.json.body || item.json }];

// Build the backup report email — both NAS boxes reported symmetrically
// (Brian, 2026-09-10: was Cold-Storage-only gating; Audio NAS is now the
// short-term primary and Cold Storage the long-term/2-year archive, so the
// report treats neither as more important than the other for "did it work").
// Payload comes from /opt/band-advance/backup/advance_backup.sh.
const b = $input.first().json;

const cs = b.coldstorage || {};
const an = b.audionas || {};
const mirror = b.mirror || {};
const failures = b.failures || [];
const warnings = b.warnings || [];

const csGood = cs.ok === true && cs.verified === true;
const anGood = an.ok === true && an.verified === true;
const mirrorGood = mirror.ok === true;
const bothGood = csGood && anGood && mirrorGood;
const overall = bothGood && failures.length === 0 ? 'COMPLETE'
  : (bothGood ? 'COMPLETE (with warnings)' : 'FAILED');
const good = bothGood && failures.length === 0;

const OK = '#065F46', BAD = '#9B2222', WARN = '#B45309';
const accent = good ? OK : (bothGood ? WARN : BAD);

const mb = (n) => n ? (n / 1048576).toFixed(1) + ' MB' : '—';
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// stamp is YYYYMMDD-HHMMSS
const st = String(b.stamp || '');
const pretty = st.length >= 15
  ? `${st.slice(0,4)}-${st.slice(4,6)}-${st.slice(6,8)} ${st.slice(9,11)}:${st.slice(11,13)}`
  : st;
const dateOnly = st.length >= 8 ? `${st.slice(0,4)}-${st.slice(4,6)}-${st.slice(6,8)}` : st;

const row = (k, v) =>
  `<tr><td style="padding:5px 14px 5px 0;color:#374151;white-space:nowrap">${k}</td>` +
  `<td style="padding:5px 0;color:#111827;font-family:Consolas,monospace">${v}</td></tr>`;

// One symmetric block per box — "Held on <Name> — N of keep" + what rotated off.
function boxBlock(name, box, good) {
  const held = Array.isArray(box.archives) ? box.archives : [];
  const pruned = Array.isArray(box.pruned) ? box.pruned : [];
  let out = '';
  if (held.length) {
    out +=
      `<h3 style="font:bold 12px/1.4 Arial,sans-serif;color:#374151;margin:22px 0 6px;` +
      `text-transform:uppercase;letter-spacing:.06em">Held on ${esc(name)} — ${held.length} of ${box.keep || '—'}</h3>` +
      '<table style="border-collapse:collapse;font:12px/1.5 Consolas,monospace">' +
      held.map((f, i) =>
        `<tr><td style="padding:2px 12px 2px 0;color:#9CA3AF">${i === 0 ? 'newest' : (i === held.length - 1 ? 'oldest' : '')}</td>` +
        `<td style="padding:2px 0;color:#111827">${esc(f)}</td></tr>`).join('') +
      '</table>';
  }
  if (pruned.length) {
    out +=
      `<h3 style="font:bold 12px/1.4 Arial,sans-serif;color:#374151;margin:22px 0 6px;` +
      `text-transform:uppercase;letter-spacing:.06em">Rotated off ${esc(name)} this run</h3>` +
      '<table style="border-collapse:collapse;font:12px/1.5 Consolas,monospace">' +
      pruned.map(f => `<tr><td style="padding:2px 0;color:#6B7280">${esc(f)}</td></tr>`).join('') +
      '</table>';
  }
  return out;
}

let rowsBlock = '';
const dbr = b.db_rows || {};
const dbKeys = Object.keys(dbr);
if (dbKeys.length) {
  rowsBlock =
    '<h3 style="font:bold 12px/1.4 Arial,sans-serif;color:#374151;margin:22px 0 6px;' +
    'text-transform:uppercase;letter-spacing:.06em">Database captured</h3>' +
    '<table style="border-collapse:collapse;font:12px/1.5 Consolas,monospace">' +
    dbKeys.map(k =>
      `<tr><td style="padding:2px 16px 2px 0;color:#374151">${esc(k)}</td>` +
      `<td style="padding:2px 0;color:#111827;text-align:right">${esc(dbr[k])}</td></tr>`).join('') +
    '</table>';
}

let problems = '';
if (failures.length || warnings.length) {
  problems =
    `<div style="margin:22px 0 0;padding:12px 14px;background:${failures.length ? '#FEE2E2' : '#FFE4B5'};` +
    'border-radius:4px;font:13px/1.6 Arial,sans-serif;color:#1F2937">' +
    (failures.length ? '<strong>Failures</strong><ul style="margin:6px 0 0;padding-left:18px">' +
      failures.map(f => `<li>${esc(f)}</li>`).join('') + '</ul>' : '') +
    (warnings.length ? '<strong style="display:block;margin-top:' + (failures.length ? '10px' : '0') +
      '">Warnings</strong><ul style="margin:6px 0 0;padding-left:18px">' +
      warnings.map(w => `<li>${esc(w)}</li>`).join('') + '</ul>' : '') +
    '</div>';
}

const statusCell = (name, isGood) =>
  `${isGood ? '&#10003;' : '&#10007;'} ${esc(name)} ${isGood ? 'verified' : 'NOT verified'}`;

const html =
  '<div style="font:14px/1.6 Arial,Helvetica,sans-serif;color:#111827;max-width:640px">' +
    `<div style="background:#1F2937;color:#fff;padding:14px 18px;border-radius:4px 4px 0 0">` +
      '<div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#9CA3AF">Band Advance — weekly backup</div>' +
      `<div style="font-size:19px;font-weight:bold;margin-top:2px">${esc(overall)}</div>` +
    '</div>' +
    `<div style="border:1px solid #E5E7EB;border-top:0;border-radius:0 0 4px 4px;padding:16px 18px">` +
      `<div style="color:${accent};font-weight:bold;margin-bottom:12px">` +
        statusCell('Audio NAS (short-term primary)', anGood) + '<br>' +
        statusCell('Cold Storage (long-term, 2-year)', csGood) + '<br>' +
        statusCell('Cold Storage — live Dropbox mirror', mirrorGood) +
      '</div>' +
      '<table style="border-collapse:collapse;font:13px/1.6 Arial,sans-serif">' +
        row('Run', esc(pretty)) +
        row('Archive', esc(b.archive || '—')) +
        row('Size', mb(b.bytes)) +
        row('Audio NAS path', esc(an.path || '—')) +
        row('Audio NAS now holding', anGood ? `${an.count || 0} of ${an.keep || '—'}` : 'unknown — could not read the NAS') +
        row('Cold Storage path', esc(cs.path || '—')) +
        row('Cold Storage now holding', csGood ? `${cs.count || 0} of ${cs.keep || '—'}` : 'unknown — could not read the NAS') +
        row('Dropbox mirror path', esc(mirror.path || '—')) +
        row('Dropbox mirror', mirrorGood ? `${mirror.files || 0} files, no extraction needed` : 'FAILED — check the VM') +
      '</table>' +
      boxBlock('Audio NAS', an, anGood) + boxBlock('Cold Storage', cs, csGood) +
      rowsBlock + problems +
      '<div style="margin-top:22px;padding-top:12px;border-top:1px solid #E5E7EB;' +
        'font:12px/1.6 Arial,sans-serif;color:#6B7280">' +
        'Restore in one command:<br>' +
        '<code style="font-family:Consolas,monospace;color:#374151">' +
        `tar xzf ${esc(b.archive || 'band-advance-*.tar.gz')} &amp;&amp; sudo ./${esc((b.archive || '').replace(/\.tar\.gz$/, '') || 'band-advance-*')}/restore.sh</code>` +
        '<br>or run <code style="font-family:Consolas,monospace;color:#374151">backup/restore_advance.command</code> from the Mac.' +
      '</div>' +
    '</div>' +
  '</div>';

const failedParts = [
  !anGood ? 'Audio NAS' : null,
  !csGood ? 'Cold Storage' : null,
  !mirrorGood ? 'Dropbox mirror' : null,
].filter(Boolean);
const subject = bothGood
  ? `Band Advance backup complete — Audio NAS + Cold Storage + mirror — ${dateOnly}`
  : `Band Advance backup FAILED (${failedParts.join(' + ')}) — ${dateOnly}`;

return [{ json: {
  to: b.to || 'blloyd@3cdc.org',
  subject,
  html
} }];
